// stream-backpressure.js
// 运行：node stream-backpressure.js  (需要 Node.js 18+)
import { Transform, Writable, pipeline } from "node:stream/promises";
import { setTimeout as sleep } from "node:timers/promises";

// 1) 生产者：用 async generator 生成 2 万条日志
//    逐条 yield，内存中永远只存在一条记录
async function* logSource(total) {
  for (let i = 0; i < total; i++) {
    yield {
      id: i,
      level: i % 7 === 0 ? "error" : "info",
      cost: (i * 13) % 500,
    };
    // 刻意不加延迟：模拟「生产远快于消费」的压力场景
  }
}

// 2) 转换流：只保留 error 且 cost > 100 的记录
const filter = new Transform({
  objectMode: true,
  transform(chunk, _enc, cb) {
    if (chunk.level === "error" && chunk.cost > 100) {
      cb(null, chunk); // 产出一条
    } else {
      cb(); // 不产出即丢弃
    }
  },
});

// 3) 消费者：慢速写入（模拟写数据库），highWaterMark 刻意设小
let written = 0;
const slowSink = new Writable({
  objectMode: true,
  highWaterMark: 8, // 缓冲区只允许 8 个对象，几乎立刻触发背压
  write(chunk, _enc, cb) {
    written++;
    sleep(20).then(() => cb()); // 每条 20ms 的慢速落盘
  },
});

// 4) pipeline 自动传递背压信号，且出错时自动清理所有流
const start = Date.now();
await pipeline(logSource(20000), filter, slowSink);

console.log(`完成：写入 ${written} 条，耗时 ${Date.now() - start}ms`);
console.log(`RSS 稳定在 ${(process.memoryUsage().rss / 1024 / 1024).toFixed(1)} MB`);

