import { Readable, Transform } from 'node:stream';

const src = Readable.from([1, 2, 3]);
const double = new Transform({
  transform(c, _e, cb) { cb(null, c * 2); },
});
const keepBig = new Transform({
  transform(c, _e, cb) { if (c > 2) cb(null, c); else cb(); },
});

src.pipe(double).pipe(keepBig);

const out = [];
for await (const c of keepBig) out.push(c);
console.log(out.join(','));
